-- Registry change for gws-mcp. PROPOSAL: NOT RUN.
-- Generated from the tool files CI kept for gateway f620199d8e8285acbacf5665d5e318c2b45f2303 (what is running) and c3a60612509250b85e3ee9618e840597f2556cc2.
-- 5 row(s) change, 0 added, 0 removed.
-- Rows for gws-mcp: 87 before, 87 after.
--   changes gmail_create_draft: input_schema_json
--   changes gmail_forward: input_schema_json
--   changes gmail_reply: input_schema_json
--   changes gmail_send: input_schema_json
--   changes gmail_update_draft: description, input_schema_json
-- Each statement is guarded by the md5 of the row's description and of input_schema_json::text
-- as the other commit's plugin served them. If the live row differs, the statement touches
-- nothing, the block raises and the transaction rolls back.
-- One transaction. Run by a person, on a confirmation that names the database. See the
-- SCRUM-390 spec for the order against the deploy.

BEGIN;
SET LOCAL standard_conforming_strings = on;
DO $registry_change$
DECLARE n int;
BEGIN
  -- gmail_create_draft
  UPDATE tools t SET description = 'Create a draft email in Gmail without sending it. The draft can be reviewed and sent later from Gmail. Returns the draft ID and a link to open it in Gmail. Accepts a plain-text body, an HTML html_body, or both — HTML is stored as multipart/alternative with a plain-text fallback. The account''s Gmail signature is added to the draft automatically, as Gmail''s own Compose does, so do not write a sign-off or signature in the body yourself; pass signature: false to leave it out. The signature goes in the draft''s HTML part, so a plain-text body is stored as multipart/alternative when the account has one. The response''s signature field reports what happened.', input_schema_json = '{"type":"object","properties":{"to":{"type":"string","description":"Recipient email address(es), comma-separated"},"subject":{"type":"string","description":"Email subject line"},"body":{"type":"string","description":"Plain-text email body. When html_body is also given, this becomes the text/plain alternative part shown by plain-text clients. One of body or html_body is required."},"html_body":{"type":"string","description":"HTML email body. The message is sent as multipart/alternative with a text/plain fallback part (body if provided, otherwise text derived from the HTML), so plain-text clients still render something readable."},"cc":{"type":"string","description":"CC recipients, comma-separated"},"bcc":{"type":"string","description":"BCC recipients, comma-separated"},"attachments":{"type":"array","maxItems":10,"description":"Files to send with the message, at most 10, 25 MB in total. Each entry is a Drive file id as a string, or {\"file_id\": \"<id>\", \"as\": \"<format>\"} to send a Google Doc, Sheet or Slides deck as a file, or a file reference. Formats: Docs pdf, docx, txt, html, md, rtf, odt, epub; Sheets pdf, xlsx, csv, tsv, html, ods; Slides pdf, pptx, txt, odp. csv and tsv export one tab: add \"tab\": \"<title>\" to choose it, otherwise the first tab goes, and the response says which. A Sheet as html arrives as a .zip of pages, one per tab; Slides as txt is the slides'' visible text only. Google Docs, Sheets and Slides passed by id alone are sent as links in the message, the way Gmail does, not as files. Other Drive files are attached as they are. A file reference is an object with a \"type\": {\"type\": \"gmail_message\", \"message_id\": \"<id>\"} attaches an email as its original .eml, {\"type\": \"gmail_attachment\", \"message_id\": \"<id>\", \"part_id\": \"<part id>\"} one attachment of an email, {\"type\": \"drive_file\", \"file_id\": \"<id>\"} a Drive file as stored, {\"type\": \"drive_export\", \"file_id\": \"<id>\", \"format\": \"pdf\"} a Google file exported, and {\"type\": \"content\", \"name\": \"<file name>\", \"base64\": \"<standard base64, one unbroken string>\"} a file the caller already holds, at most 1 MB. A reference may carry an \"account\" naming the connected Google account that holds the email or file. Several entries may be references. Two attachments may not share a filename. To show an image in the body rather than at the bottom, reference it in html_body as <img src=\"cid:FILENAME\">, where FILENAME is its Drive filename with any character other than letters, digits, dot, dash and underscore replaced by an underscore. Sharing a Drive link is the sender''s responsibility; nothing here changes who can open a file. The response''s attachments field reports each file as attached, inline, linked or exported, with its size and the SHA-256 of the bytes that went into the message; a file sent as a link has neither.","items":{"anyOf":[{"type":"string","description":"A Drive file id."},{"type":"object","properties":{"file_id":{"type":"string","description":"A Drive file id."},"as":{"type":"string","enum":["pdf","docx","txt","html","md","rtf","odt","epub","xlsx","csv","tsv","ods","pptx","odp"],"description":"Export a Google Doc, Sheet or Slides deck in this format."},"tab":{"type":"string","description":"For a Sheet as csv or tsv: the tab to export, by title. Defaults to the first tab."}},"required":["file_id"]},{"type":"object","description":"A file reference, resolved by the gateway and attached in this entry''s place.","properties":{"type":{"type":"string","enum":["gmail_message","gmail_attachment","drive_file","drive_export","content"],"description":"The kind of file reference."},"message_id":{"type":"string","description":"With gmail_message and gmail_attachment: the Gmail message id."},"part_id":{"type":"string","description":"With gmail_attachment: the attachment''s part id as gmail_read lists it."},"file_id":{"type":"string","description":"With drive_file and drive_export: the Drive file id."},"format":{"type":"string","description":"With drive_export: the format to export to, such as pdf."},"account":{"type":"string","description":"Which connected Google account holds the email or file. Not taken with content."},"name":{"type":"string","description":"With content: the file''s name, with its extension."},"base64":{"type":"string","description":"With content: the file in standard base64 as one unbroken string, at most 1 MB decoded."},"mime_type":{"type":"string","description":"With content, optional: the file''s type; omitted, it comes from the name''s extension."}},"required":["type"]}]}},"signature":{"type":"boolean","description":"Set false to write the draft without the account''s Gmail signature, and to skip the lookup entirely. Defaults to true."}},"required":["to","subject"]}'::jsonb, read_only_hint = false, updated_at = now()
  FROM mcp_servers s
  WHERE s.id = t.mcp_server_id AND s.slug = 'gws-mcp' AND t.name = 'gmail_create_draft'
    AND md5(t.description) = 'a375d8eefad6b4e6079dee1208fefc21'
    AND md5(t.input_schema_json::text) = '5d2faaac71cfea4322f0b69a42a42731'
    AND t.read_only_hint IS NOT DISTINCT FROM false
  ;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'forward gmail_create_draft: expected 1 row, updated %', n; END IF;

  -- gmail_forward
  UPDATE tools t SET description = 'Forward an existing email to another recipient. The account''s Gmail signature is appended automatically, so do not write a sign-off or signature in the body yourself; pass signature: false to send without it. The signature goes in the message''s HTML part, so a plain-text body is sent as multipart/alternative when the account has one. The response''s signature field reports what happened.', input_schema_json = '{"type":"object","properties":{"message_id":{"type":"string","description":"The Gmail message ID to forward"},"to":{"type":"string","description":"Recipient email address to forward to"},"body":{"type":"string","description":"Optional plain-text note included above the forwarded message"},"html_body":{"type":"string","description":"Optional HTML note included above the forwarded message. The forward goes out with both an HTML part and a plain-text part, and the forwarded block is formatted with Gmail styling. Provide body or html_body, not both."},"attachments":{"type":"array","maxItems":10,"description":"Files to send with the message, at most 10, 25 MB in total. Each entry is a Drive file id as a string, or {\"file_id\": \"<id>\", \"as\": \"<format>\"} to send a Google Doc, Sheet or Slides deck as a file, or a file reference. Formats: Docs pdf, docx, txt, html, md, rtf, odt, epub; Sheets pdf, xlsx, csv, tsv, html, ods; Slides pdf, pptx, txt, odp. csv and tsv export one tab: add \"tab\": \"<title>\" to choose it, otherwise the first tab goes, and the response says which. A Sheet as html arrives as a .zip of pages, one per tab; Slides as txt is the slides'' visible text only. Google Docs, Sheets and Slides passed by id alone are sent as links in the message, the way Gmail does, not as files. Other Drive files are attached as they are. A file reference is an object with a \"type\": {\"type\": \"gmail_message\", \"message_id\": \"<id>\"} attaches an email as its original .eml, {\"type\": \"gmail_attachment\", \"message_id\": \"<id>\", \"part_id\": \"<part id>\"} one attachment of an email, {\"type\": \"drive_file\", \"file_id\": \"<id>\"} a Drive file as stored, {\"type\": \"drive_export\", \"file_id\": \"<id>\", \"format\": \"pdf\"} a Google file exported, and {\"type\": \"content\", \"name\": \"<file name>\", \"base64\": \"<standard base64, one unbroken string>\"} a file the caller already holds, at most 1 MB. A reference may carry an \"account\" naming the connected Google account that holds the email or file. Several entries may be references. Two attachments may not share a filename. To show an image in the body rather than at the bottom, reference it in html_body as <img src=\"cid:FILENAME\">, where FILENAME is its Drive filename with any character other than letters, digits, dot, dash and underscore replaced by an underscore. Sharing a Drive link is the sender''s responsibility; nothing here changes who can open a file. The response''s attachments field reports each file as attached, inline, linked or exported, with its size and the SHA-256 of the bytes that went into the message; a file sent as a link has neither.","items":{"anyOf":[{"type":"string","description":"A Drive file id."},{"type":"object","properties":{"file_id":{"type":"string","description":"A Drive file id."},"as":{"type":"string","enum":["pdf","docx","txt","html","md","rtf","odt","epub","xlsx","csv","tsv","ods","pptx","odp"],"description":"Export a Google Doc, Sheet or Slides deck in this format."},"tab":{"type":"string","description":"For a Sheet as csv or tsv: the tab to export, by title. Defaults to the first tab."}},"required":["file_id"]},{"type":"object","description":"A file reference, resolved by the gateway and attached in this entry''s place.","properties":{"type":{"type":"string","enum":["gmail_message","gmail_attachment","drive_file","drive_export","content"],"description":"The kind of file reference."},"message_id":{"type":"string","description":"With gmail_message and gmail_attachment: the Gmail message id."},"part_id":{"type":"string","description":"With gmail_attachment: the attachment''s part id as gmail_read lists it."},"file_id":{"type":"string","description":"With drive_file and drive_export: the Drive file id."},"format":{"type":"string","description":"With drive_export: the format to export to, such as pdf."},"account":{"type":"string","description":"Which connected Google account holds the email or file. Not taken with content."},"name":{"type":"string","description":"With content: the file''s name, with its extension."},"base64":{"type":"string","description":"With content: the file in standard base64 as one unbroken string, at most 1 MB decoded."},"mime_type":{"type":"string","description":"With content, optional: the file''s type; omitted, it comes from the name''s extension."}},"required":["type"]}]}},"include_original_attachments":{"type":"boolean","description":"The original message''s own attachments are forwarded with it, counted in the 25 MB limit. Set false to forward the text alone. Defaults to true."},"signature":{"type":"boolean","description":"Set false to send without the account''s Gmail signature, and to skip the lookup entirely. Defaults to true."}},"required":["message_id","to"]}'::jsonb, read_only_hint = false, updated_at = now()
  FROM mcp_servers s
  WHERE s.id = t.mcp_server_id AND s.slug = 'gws-mcp' AND t.name = 'gmail_forward'
    AND md5(t.description) = '272a6fe6895542926caa724915f1f9db'
    AND md5(t.input_schema_json::text) = '15b7a6b3fb68a449ac1aafc375941f75'
    AND t.read_only_hint IS NOT DISTINCT FROM false
  ;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'forward gmail_forward: expected 1 row, updated %', n; END IF;

  -- gmail_reply
  UPDATE tools t SET description = 'Reply to an existing email in its thread. The reply is addressed the way Gmail''s own Reply does it: to the original''s Reply-To when it has one, otherwise to its sender; when you sent the original yourself, to the people it was sent to. Pass reply_all: true to include everyone else on the original as well. The response reports the To and Cc the reply went to; when a Reply-To meant the original''s sender was not among them, it also carries reply_to_used: true and original_from, so check to against who you meant to answer, or pass expected_to and the reply is refused instead of sent when it would go anywhere else. A body is required: pass body or html_body. The account''s Gmail signature is appended automatically, so do not write a sign-off or signature in the body yourself; pass signature: false to send without it. The signature goes in the message''s HTML part, so a plain-text body is sent as multipart/alternative when the account has one. The response''s signature field reports what happened.', input_schema_json = '{"type":"object","properties":{"message_id":{"type":"string","description":"The Gmail message ID to reply to"},"body":{"type":"string","description":"Reply body text (plain). One of body or html_body is required."},"html_body":{"type":"string","description":"HTML reply body. The reply goes out with both an HTML part and a plain-text part derived from it, and the original message is quoted beneath with Gmail styling. Provide body or html_body, not both; one of them is required."},"reply_all":{"type":"boolean","description":"Default false: the reply goes to one party, the original''s Reply-To or sender (or, for a message you sent, its recipients). Set true to reply to everyone: the original''s other To recipients are added to To and its Cc recipients to Cc, without your own addresses."},"expected_to":{"type":"string","description":"Optional guard: the address or addresses, comma separated, you mean this reply to reach. The reply is refused before anything is sent unless it would go to exactly these (every To address, and every Cc address under reply_all; order and case are ignored). Use it when it matters who receives the reply: the recipients come from the original message''s headers, and a Reply-To can name someone other than the sender you see."},"attachments":{"type":"array","maxItems":10,"description":"Files to send with the message, at most 10, 25 MB in total. Each entry is a Drive file id as a string, or {\"file_id\": \"<id>\", \"as\": \"<format>\"} to send a Google Doc, Sheet or Slides deck as a file, or a file reference. Formats: Docs pdf, docx, txt, html, md, rtf, odt, epub; Sheets pdf, xlsx, csv, tsv, html, ods; Slides pdf, pptx, txt, odp. csv and tsv export one tab: add \"tab\": \"<title>\" to choose it, otherwise the first tab goes, and the response says which. A Sheet as html arrives as a .zip of pages, one per tab; Slides as txt is the slides'' visible text only. Google Docs, Sheets and Slides passed by id alone are sent as links in the message, the way Gmail does, not as files. Other Drive files are attached as they are. A file reference is an object with a \"type\": {\"type\": \"gmail_message\", \"message_id\": \"<id>\"} attaches an email as its original .eml, {\"type\": \"gmail_attachment\", \"message_id\": \"<id>\", \"part_id\": \"<part id>\"} one attachment of an email, {\"type\": \"drive_file\", \"file_id\": \"<id>\"} a Drive file as stored, {\"type\": \"drive_export\", \"file_id\": \"<id>\", \"format\": \"pdf\"} a Google file exported, and {\"type\": \"content\", \"name\": \"<file name>\", \"base64\": \"<standard base64, one unbroken string>\"} a file the caller already holds, at most 1 MB. A reference may carry an \"account\" naming the connected Google account that holds the email or file. Several entries may be references. Two attachments may not share a filename. To show an image in the body rather than at the bottom, reference it in html_body as <img src=\"cid:FILENAME\">, where FILENAME is its Drive filename with any character other than letters, digits, dot, dash and underscore replaced by an underscore. Sharing a Drive link is the sender''s responsibility; nothing here changes who can open a file. The response''s attachments field reports each file as attached, inline, linked or exported, with its size and the SHA-256 of the bytes that went into the message; a file sent as a link has neither.","items":{"anyOf":[{"type":"string","description":"A Drive file id."},{"type":"object","properties":{"file_id":{"type":"string","description":"A Drive file id."},"as":{"type":"string","enum":["pdf","docx","txt","html","md","rtf","odt","epub","xlsx","csv","tsv","ods","pptx","odp"],"description":"Export a Google Doc, Sheet or Slides deck in this format."},"tab":{"type":"string","description":"For a Sheet as csv or tsv: the tab to export, by title. Defaults to the first tab."}},"required":["file_id"]},{"type":"object","description":"A file reference, resolved by the gateway and attached in this entry''s place.","properties":{"type":{"type":"string","enum":["gmail_message","gmail_attachment","drive_file","drive_export","content"],"description":"The kind of file reference."},"message_id":{"type":"string","description":"With gmail_message and gmail_attachment: the Gmail message id."},"part_id":{"type":"string","description":"With gmail_attachment: the attachment''s part id as gmail_read lists it."},"file_id":{"type":"string","description":"With drive_file and drive_export: the Drive file id."},"format":{"type":"string","description":"With drive_export: the format to export to, such as pdf."},"account":{"type":"string","description":"Which connected Google account holds the email or file. Not taken with content."},"name":{"type":"string","description":"With content: the file''s name, with its extension."},"base64":{"type":"string","description":"With content: the file in standard base64 as one unbroken string, at most 1 MB decoded."},"mime_type":{"type":"string","description":"With content, optional: the file''s type; omitted, it comes from the name''s extension."}},"required":["type"]}]}},"signature":{"type":"boolean","description":"Set false to send without the account''s Gmail signature, and to skip the lookup entirely. Defaults to true."}},"required":["message_id"]}'::jsonb, read_only_hint = false, updated_at = now()
  FROM mcp_servers s
  WHERE s.id = t.mcp_server_id AND s.slug = 'gws-mcp' AND t.name = 'gmail_reply'
    AND md5(t.description) = '2cea811918b3fd02f00450bdfcaec1d8'
    AND md5(t.input_schema_json::text) = 'e7dd830bccdafbaf2afc510d9e8cc7e6'
    AND t.read_only_hint IS NOT DISTINCT FROM false
  ;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'forward gmail_reply: expected 1 row, updated %', n; END IF;

  -- gmail_send
  UPDATE tools t SET description = 'Send a new email via Gmail. Composes and sends an email message to the specified recipients. Accepts a plain-text body, an HTML html_body, or both — HTML is sent as multipart/alternative with a plain-text fallback. The account''s Gmail signature is appended automatically, so do not write a sign-off or signature in the body yourself; pass signature: false to send without it. The signature goes in the message''s HTML part, so a plain-text body is sent as multipart/alternative when the account has one. The response''s signature field reports what happened.', input_schema_json = '{"type":"object","properties":{"to":{"type":"string","description":"Recipient email address(es), comma-separated"},"subject":{"type":"string","description":"Email subject line"},"body":{"type":"string","description":"Plain-text email body. When html_body is also given, this becomes the text/plain alternative part shown by plain-text clients. One of body or html_body is required."},"html_body":{"type":"string","description":"HTML email body. The message is sent as multipart/alternative with a text/plain fallback part (body if provided, otherwise text derived from the HTML), so plain-text clients still render something readable."},"cc":{"type":"string","description":"CC recipients, comma-separated"},"bcc":{"type":"string","description":"BCC recipients, comma-separated"},"attachments":{"type":"array","maxItems":10,"description":"Files to send with the message, at most 10, 25 MB in total. Each entry is a Drive file id as a string, or {\"file_id\": \"<id>\", \"as\": \"<format>\"} to send a Google Doc, Sheet or Slides deck as a file, or a file reference. Formats: Docs pdf, docx, txt, html, md, rtf, odt, epub; Sheets pdf, xlsx, csv, tsv, html, ods; Slides pdf, pptx, txt, odp. csv and tsv export one tab: add \"tab\": \"<title>\" to choose it, otherwise the first tab goes, and the response says which. A Sheet as html arrives as a .zip of pages, one per tab; Slides as txt is the slides'' visible text only. Google Docs, Sheets and Slides passed by id alone are sent as links in the message, the way Gmail does, not as files. Other Drive files are attached as they are. A file reference is an object with a \"type\": {\"type\": \"gmail_message\", \"message_id\": \"<id>\"} attaches an email as its original .eml, {\"type\": \"gmail_attachment\", \"message_id\": \"<id>\", \"part_id\": \"<part id>\"} one attachment of an email, {\"type\": \"drive_file\", \"file_id\": \"<id>\"} a Drive file as stored, {\"type\": \"drive_export\", \"file_id\": \"<id>\", \"format\": \"pdf\"} a Google file exported, and {\"type\": \"content\", \"name\": \"<file name>\", \"base64\": \"<standard base64, one unbroken string>\"} a file the caller already holds, at most 1 MB. A reference may carry an \"account\" naming the connected Google account that holds the email or file. Several entries may be references. Two attachments may not share a filename. To show an image in the body rather than at the bottom, reference it in html_body as <img src=\"cid:FILENAME\">, where FILENAME is its Drive filename with any character other than letters, digits, dot, dash and underscore replaced by an underscore. Sharing a Drive link is the sender''s responsibility; nothing here changes who can open a file. The response''s attachments field reports each file as attached, inline, linked or exported, with its size and the SHA-256 of the bytes that went into the message; a file sent as a link has neither.","items":{"anyOf":[{"type":"string","description":"A Drive file id."},{"type":"object","properties":{"file_id":{"type":"string","description":"A Drive file id."},"as":{"type":"string","enum":["pdf","docx","txt","html","md","rtf","odt","epub","xlsx","csv","tsv","ods","pptx","odp"],"description":"Export a Google Doc, Sheet or Slides deck in this format."},"tab":{"type":"string","description":"For a Sheet as csv or tsv: the tab to export, by title. Defaults to the first tab."}},"required":["file_id"]},{"type":"object","description":"A file reference, resolved by the gateway and attached in this entry''s place.","properties":{"type":{"type":"string","enum":["gmail_message","gmail_attachment","drive_file","drive_export","content"],"description":"The kind of file reference."},"message_id":{"type":"string","description":"With gmail_message and gmail_attachment: the Gmail message id."},"part_id":{"type":"string","description":"With gmail_attachment: the attachment''s part id as gmail_read lists it."},"file_id":{"type":"string","description":"With drive_file and drive_export: the Drive file id."},"format":{"type":"string","description":"With drive_export: the format to export to, such as pdf."},"account":{"type":"string","description":"Which connected Google account holds the email or file. Not taken with content."},"name":{"type":"string","description":"With content: the file''s name, with its extension."},"base64":{"type":"string","description":"With content: the file in standard base64 as one unbroken string, at most 1 MB decoded."},"mime_type":{"type":"string","description":"With content, optional: the file''s type; omitted, it comes from the name''s extension."}},"required":["type"]}]}},"signature":{"type":"boolean","description":"Set false to send without the account''s Gmail signature, and to skip the lookup entirely. Defaults to true."}},"required":["to","subject"]}'::jsonb, read_only_hint = false, updated_at = now()
  FROM mcp_servers s
  WHERE s.id = t.mcp_server_id AND s.slug = 'gws-mcp' AND t.name = 'gmail_send'
    AND md5(t.description) = '99b8971709394047990cc07cb3449340'
