  -- gmail_update_draft
  UPDATE tools t SET description = 'Update an existing draft email in Gmail. This fully replaces the draft''s message content (Gmail API does not support partial edits), attachments included: files the draft held, including any attached by a file reference, are dropped unless they are passed again in attachments. If thread_id is omitted, the tool preserves the existing thread automatically. The account''s Gmail signature is added to the draft automatically, as Gmail''s own Compose does, so do not write a sign-off or signature in the body yourself; pass signature: false to leave it out. The signature goes in the draft''s HTML part, so a plain-text body is stored as multipart/alternative when the account has one. The response''s signature field reports what happened.', input_schema_json = '{"type":"object","properties":{"draft_id":{"type":"string","description":"The Gmail draft ID to update"},"to":{"type":"string","description":"Recipient email address(es), comma-separated"},"subject":{"type":"string","description":"Email subject line"},"body":{"type":"string","description":"Plain-text email body. When html_body is also given, this becomes the text/plain alternative part shown by plain-text clients. One of body or html_body is required."},"html_body":{"type":"string","description":"HTML email body. The message is sent as multipart/alternative with a text/plain fallback part (body if provided, otherwise text derived from the HTML), so plain-text clients still render something readable."},"cc":{"type":"string","description":"CC recipients, comma-separated"},"bcc":{"type":"string","description":"BCC recipients, comma-separated"},"thread_id":{"type":"string","description":"Thread ID to preserve threading. If omitted, the existing draft''s thread is preserved automatically."},"attachments":{"type":"array","maxItems":10,"description":"Files to send with the message, at most 10, 25 MB in total. Each entry is a Drive file id as a string, or {\"file_id\": \"<id>\", \"as\": \"<format>\"} to send a Google Doc, Sheet or Slides deck as a file, or a file reference. Formats: Docs pdf, docx, txt, html, md, rtf, odt, epub; Sheets pdf, xlsx, csv, tsv, html, ods; Slides pdf, pptx, txt, odp. csv and tsv export one tab: add \"tab\": \"<title>\" to choose it, otherwise the first tab goes, and the response says which. A Sheet as html arrives as a .zip of pages, one per tab; Slides as txt is the slides'' visible text only. Google Docs, Sheets and Slides passed by id alone are sent as links in the message, the way Gmail does, not as files. Other Drive files are attached as they are. A file reference is an object with a \"type\": {\"type\": \"gmail_message\", \"message_id\": \"<id>\"} attaches an email as its original .eml, {\"type\": \"gmail_attachment\", \"message_id\": \"<id>\", \"part_id\": \"<part id>\"} one attachment of an email, {\"type\": \"drive_file\", \"file_id\": \"<id>\"} a Drive file as stored, {\"type\": \"drive_export\", \"file_id\": \"<id>\", \"format\": \"pdf\"} a Google file exported, and {\"type\": \"content\", \"name\": \"<file name>\", \"base64\": \"<standard base64, one unbroken string>\"} a file the caller already holds, at most 1 MB. A reference may carry an \"account\" naming the connected Google account that holds the email or file. Several entries may be references. Two attachments may not share a filename. To show an image in the body rather than at the bottom, reference it in html_body as <img src=\"cid:FILENAME\">, where FILENAME is its Drive filename with any character other than letters, digits, dot, dash and underscore replaced by an underscore. Sharing a Drive link is the sender''s responsibility; nothing here changes who can open a file. The response''s attachments field reports each file as attached, inline, linked or exported, with its size and the SHA-256 of the bytes that went into the message; a file sent as a link has neither.","items":{"anyOf":[{"type":"string","description":"A Drive file id."},{"type":"object","properties":{"file_id":{"type":"string","description":"A Drive file id."},"as":{"type":"string","enum":["pdf","docx","txt","html","md","rtf","odt","epub","xlsx","csv","tsv","ods","pptx","odp"],"description":"Export a Google Doc, Sheet or Slides deck in this format."},"tab":{"type":"string","description":"For a Sheet as csv or tsv: the tab to export, by title. Defaults to the first tab."}},"required":["file_id"]},{"type":"object","description":"A file reference, resolved by the gateway and attached in this entry''s place.","properties":{"type":{"type":"string","enum":["gmail_message","gmail_attachment","drive_file","drive_export","content"],"description":"The kind of file reference."},"message_id":{"type":"string","description":"With gmail_message and gmail_attachment: the Gmail message id."},"part_id":{"type":"string","description":"With gmail_attachment: the attachment''s part id as gmail_read lists it."},"file_id":{"type":"string","description":"With drive_file and drive_export: the Drive file id."},"format":{"type":"string","description":"With drive_export: the format to export to, such as pdf."},"account":{"type":"string","description":"Which connected Google account holds the email or file. Not taken with content."},"name":{"type":"string","description":"With content: the file''s name, with its extension."},"base64":{"type":"string","description":"With content: the file in standard base64 as one unbroken string, at most 1 MB decoded."},"mime_type":{"type":"string","description":"With content, optional: the file''s type; omitted, it comes from the name''s extension."}},"required":["type"]}]}},"signature":{"type":"boolean","description":"Set false to write the draft without the account''s Gmail signature, and to skip the lookup entirely. Defaults to true."}},"required":["draft_id","to","subject"]}'::jsonb, read_only_hint = false, updated_at = now()
  FROM mcp_servers s
  WHERE s.id = t.mcp_server_id AND s.slug = 'gws-mcp' AND t.name = 'gmail_update_draft'
    AND md5(t.description) = '6d580482d6b85bbd25a6e79ab9a88dae'
    AND md5(t.input_schema_json::text) = 'ff744316329d1395354843ae78bf1c7d'
    AND t.read_only_hint IS NOT DISTINCT FROM false
  ;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'forward gmail_update_draft: expected 1 row, updated %', n; END IF;

  SELECT count(*) INTO n FROM tools t JOIN mcp_servers s ON s.id = t.mcp_server_id WHERE s.slug = 'gws-mcp';
  IF n <> 87 THEN RAISE EXCEPTION 'rows for gws-mcp: expected 87, found %', n; END IF;
END
$registry_change$;
SELECT t.name, md5(t.description) AS description_md5, md5(t.input_schema_json::text) AS schema_md5, t.read_only_hint, t.updated_at
FROM mcp_servers s JOIN tools t ON s.id = t.mcp_server_id
WHERE s.slug = 'gws-mcp' AND t.name IN ('gmail_create_draft', 'gmail_forward', 'gmail_reply', 'gmail_send', 'gmail_update_draft');
COMMIT;
